PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('Administrator','Lead','Technician')), lead_id INTEGER REFERENCES users(id), active INTEGER NOT NULL DEFAULT 1, must_change INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS access(user_id INTEGER REFERENCES users(id), building_id INTEGER REFERENCES buildings(id), PRIMARY KEY(user_id,building_id));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id),expires REAL NOT NULL,version INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS buildings(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lines(id INTEGER PRIMARY KEY,building_id INTEGER NOT NULL REFERENCES buildings(id),code TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',UNIQUE(building_id,code));
CREATE TABLE IF NOT EXISTS types(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS machines(id INTEGER PRIMARY KEY,line_id INTEGER NOT NULL REFERENCES lines(id),type_id INTEGER NOT NULL REFERENCES types(id),station TEXT NOT NULL,asset_tag TEXT UNIQUE NOT NULL,serial TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'Operating' CHECK(status IN ('Operating','Maintenance','Stopped','Retired')),UNIQUE(line_id,station));
CREATE TABLE IF NOT EXISTS parts(id INTEGER PRIMARY KEY,sku TEXT UNIQUE NOT NULL,name TEXT NOT NULL,bin TEXT NOT NULL,supplier TEXT NOT NULL DEFAULT '',supplier_number TEXT NOT NULL DEFAULT '',cost REAL NOT NULL CHECK(cost>=0),stock INTEGER NOT NULL CHECK(stock>=0),threshold INTEGER NOT NULL CHECK(threshold>=0),target INTEGER NOT NULL CHECK(target>=threshold),lead_days INTEGER NOT NULL DEFAULT 0 CHECK(lead_days>=0),interval_days INTEGER NOT NULL CHECK(interval_days>0));
CREATE TABLE IF NOT EXISTS compatibility(part_id INTEGER REFERENCES parts(id),type_id INTEGER REFERENCES types(id),PRIMARY KEY(part_id,type_id));
CREATE TABLE IF NOT EXISTS requests(id INTEGER PRIMARY KEY,machine_id INTEGER NOT NULL REFERENCES machines(id),part_id INTEGER NOT NULL REFERENCES parts(id),quantity INTEGER NOT NULL CHECK(quantity>0),technician_id INTEGER NOT NULL REFERENCES users(id),lead_id INTEGER REFERENCES users(id),early INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN ('Pending','Approved','Rejected','Completed','Cancelled')),reason TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',created TEXT NOT NULL,reviewer_id INTEGER REFERENCES users(id),review_comment TEXT,reviewed TEXT,operation_key TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS maintenance(id INTEGER PRIMARY KEY,request_id INTEGER UNIQUE NOT NULL REFERENCES requests(id),machine_id INTEGER NOT NULL REFERENCES machines(id),part_id INTEGER NOT NULL REFERENCES parts(id),technician_id INTEGER NOT NULL REFERENCES users(id),quantity INTEGER NOT NULL,unit_cost REAL NOT NULL,replaced TEXT NOT NULL,location_snapshot TEXT NOT NULL,reason TEXT NOT NULL,early INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ledger(id INTEGER PRIMARY KEY,part_id INTEGER NOT NULL REFERENCES parts(id),delta INTEGER NOT NULL,reason TEXT NOT NULL,actor_id INTEGER REFERENCES users(id),created TEXT NOT NULL,operation_key TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),message TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,actor_id INTEGER REFERENCES users(id),action TEXT NOT NULL,detail TEXT NOT NULL,created TEXT NOT NULL);
-- Schema version is managed by Store initialization and ordered migrations.
